    async function sessionsDialog(){requireSource();var container=node('div'),search=input(''),list=node('div'),offset=0;container.appendChild(labelled('Search discovered sessions',search));container.appendChild(list);async function refresh(){var value=await call('/sessions?source_id='+state.source.id+'&offset='+offset+'&search='+encodeURIComponent(search.value));list.replaceChildren();(value.sessions||[]).forEach(function(item){var row=node('div',undefined,'adn-grid');row.appendChild(node('span',item.name+' · '+item.status));row.appendChild(button('Load APIs',async function(){state.document=null;state.collection=null;state.selection.clear();await bridge.loadSession(item.id);closeDialogs();renderGrid();}));list.appendChild(row);});}search.oninput=function(){offset=0;refresh().catch(error);};container.appendChild(button('Previous',function(){offset=Math.max(0,offset-25);return refresh();}));container.appendChild(button('Next',function(){offset+=25;return refresh();}));if(dialogs.sessions)dialogs.sessions.remove();dialogFor('sessions','API Discovered',container);await refresh();show('sessions');}
    window.qaDiscoveryArtifacts=async function(sourceId){try{if(state.captureActive||state.executing)throw new Error('Finish the current recording or replay first.');await loadSources();var source=state.sources.find(function(item){return Number(item.id)===Number(sourceId);});if(!source)throw new Error('Managed source document is unavailable.');fields.forEach(function(field,index){selectors[index].value=String(source[field]||'');refreshHierarchy(index+1);});state.artifactMode=true;state.document=null;state.collection=null;state.selection.clear();await loadCollections();show(2);}catch(err){error(err);}};
